// Flashcards dos temas do Estratégia (cronograma de 02/11/2026) sem cartão nas Revisões do VDE. r: 'E'.
// Texto reescrito a partir dos capítulos do Estratégia (nada copiado); b só quando o capítulo cita o dispositivo.
window.FC_VDE = (window.FC_VDE || []).concat([
  { id: "est-iter-criminis-01", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Quais são as quatro etapas do iter criminis no crime doloso?", v: "Cogitação, preparação (atos preparatórios), execução e consumação.", b: null },
  { id: "est-iter-criminis-02", d: "Direito Penal", r: "E", t: "Iter criminis", f: "A cogitação e os atos preparatórios são puníveis?", v: "A cogitação nunca é punida, pois não atinge bem jurídico alheio. Os atos preparatórios, em regra, também não, salvo quando a lei os transforma em crime autônomo.", b: null, p: "Exceções: associação criminosa (art. 288, CP) e petrechos para falsificação de moeda (art. 291, CP) punem como crime próprio o que seria mera preparação." },
  { id: "est-iter-criminis-03", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Qual critério a doutrina majoritária usa para definir o início da execução?", v: "O critério objetivo-individual: a execução começa no momento imediatamente anterior à prática do verbo do tipo, quando o agente, conforme seu plano, passa a invadir a esfera do bem jurídico alheio.", b: null },
  { id: "est-iter-criminis-04", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Quando há tentativa e qual a consequência na pena?", v: "Quando, iniciada a execução, o crime não se consuma por circunstâncias alheias à vontade do agente. Salvo disposição em contrário, aplica-se a pena do crime consumado reduzida de 1/3 a 2/3.", b: "art. 14, II e parágrafo único, CP", p: "Mandante que contrata executor que desiste antes de iniciar a execução não responde por nada: o fato ficou na preparação." },
  { id: "est-iter-criminis-05", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Qual a diferença entre desistência voluntária e arrependimento eficaz?", v: "Na desistência, o agente abandona a execução ainda em curso; no arrependimento eficaz, ele esgota a execução e depois age para impedir o resultado. Em ambos afasta-se a tentativa e ele responde só pelos atos já praticados.", b: "art. 15, CP", p: "Atirou uma vez, ainda tinha munição e foi embora: é desistência voluntária, responde pela lesão já causada, não por tentativa de homicídio." },
  { id: "est-iter-criminis-06", d: "Direito Penal", r: "E", t: "Iter criminis", f: "Quais os requisitos do arrependimento posterior e seu efeito?", v: "Crime sem violência ou grave ameaça à pessoa, reparação do dano ou restituição da coisa por ato voluntário até o recebimento da denúncia ou queixa. Reduz a pena de 1/3 a 2/3 e pressupõe crime consumado.", b: "art. 16, CP", p: "Não se aplica a roubo ou a qualquer crime com violência ou grave ameaça, nem a crime apenas tentado." },
  { id: "est-iter-criminis-07", d: "Direito Penal", r: "E", t: "Iter criminis", f: "O que é crime impossível e qual a consequência?", v: "Ocorre quando a consumação é impossível por ineficácia absoluta do meio ou impropriedade absoluta do objeto (ex.: arma desmuniciada, matar quem já está morto). A tentativa não é punida e o fato é atípico.", b: "art. 17, CP", p: "Para o STJ, loja com vigilância e câmeras não torna o furto crime impossível. Já o flagrante preparado gera crime impossível (Súmula 145 STF)." },
  { id: "est-intervencao-do-estado-na-01", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Quais são as modalidades de intervenção do Estado na propriedade?", v: "Limitação administrativa, servidão administrativa, ocupação temporária, requisição, tombamento e desapropriação, sendo esta a mais drástica, pois retira a propriedade.", b: null },
  { id: "est-intervencao-do-estado-na-02", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "O que caracteriza a limitação administrativa e ela gera indenização?", v: "É imposição geral e abstrata, baseada no poder de polícia, dirigida a proprietários indeterminados para adequar a propriedade à função social. Em regra é gratuita; só indeniza se reduzir o valor econômico do bem.", b: null, p: "Quem compra o imóvel depois de a limitação já estar imposta não tem direito a indenização." },
  { id: "est-intervencao-do-estado-na-03", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Quais as características da servidão administrativa?", v: "É ônus real sobre imóvel determinado, para obra ou serviço de utilidade pública (ex.: passagem de linhas de energia). Institui-se por acordo ou sentença, deve ser registrada no Registro de Imóveis e dura enquanto subsistir a necessidade pública.", b: null, p: "Não é direito pessoal nem tem prazo determinado." },
  { id: "est-intervencao-do-estado-na-04", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "A servidão administrativa gera indenização?", v: "Em regra não. Só há indenização se houver dano efetivo à propriedade, e ela nunca pode chegar ao valor total do bem, pois há mera restrição, não perda.", b: "art. 40, DL 3.365/41" },
  { id: "est-intervencao-do-estado-na-05", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "O que é a ocupação temporária e como é indenizada?", v: "Uso transitório de imóvel particular, em necessidade pública normal, para obras ou serviços (ex.: terreno não edificado vizinho à obra para guardar máquinas). Instituída por ato administrativo, é indenizada ao final, por ação própria, se houver prejuízo.", b: "art. 36, DL 3.365/41" },
  { id: "est-intervencao-do-estado-na-06", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Como a requisição se diferencia da ocupação temporária?", v: "A requisição pressupõe iminente perigo e pode recair sobre bens móveis, imóveis e serviços; a indenização é sempre posterior e só se houver dano. A ocupação temporária decorre de necessidade pública comum, sem perigo.", b: null },
  { id: "est-intervencao-do-estado-na-07", d: "Direito Administrativo", r: "E", t: "Intervenção do Estado na propriedade", f: "Quais os pontos principais do tombamento?", v: "Protege o patrimônio histórico e artístico, podendo recair sobre móveis e imóveis. Cabe ao proprietário conservar o bem (salvo se não tiver recursos), só indeniza se houver desvalorização e admite destombamento se desaparecer o motivo.", b: null, p: "O STJ já admitiu que Município tombe bem estadual, porque tombar não transfere a propriedade (diferente da desapropriação)." },
  { id: "est-sociedades-em-conta-de-p-01", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Por que a sociedade em conta de participação não tem personalidade jurídica?", v: "Porque a própria lei não a confere, ao contrário da sociedade em comum, que fica sem personalidade por opção dos sócios de não registrá-la.", b: "art. 993, CC" },
  { id: "est-sociedades-em-conta-de-p-02", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Quem exerce a atividade na sociedade em conta de participação?", v: "Somente o sócio ostensivo, em nome próprio e sob sua exclusiva responsabilidade; os demais apenas participam dos resultados.", b: "art. 991, CC" },
  { id: "est-sociedades-em-conta-de-p-03", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Perante quem responde o sócio participante (oculto)?", v: "Só perante o sócio ostensivo, nos termos do contrato. Perante terceiros, apenas o ostensivo se obriga.", b: "art. 991, parágrafo único, CC", p: "O terceiro que contratou com o ostensivo não pode cobrar o sócio participante." },
  { id: "est-sociedades-em-conta-de-p-04", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "A sociedade em conta de participação tem nome empresarial?", v: "Não. Como não tem personalidade, também não tem nome empresarial; os negócios são feitos em nome do sócio ostensivo.", b: null },
  { id: "est-sociedades-em-conta-de-p-05", d: "Direito Empresarial", r: "E", t: "Sociedades em conta de participação", f: "Para que costuma servir a sociedade em conta de participação na prática?", v: "Funciona como instrumento de investimento em negócios específicos, com investidor que não quer aparecer (ex.: investidor-anjo em startup), ficando como sócio participante.", b: null },
  { id: "est-sociedades-limitadas-01", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Qual a responsabilidade dos sócios na sociedade limitada?", v: "Cada sócio responde até o valor de suas quotas, mas todos respondem solidariamente pela integralização do capital social.", b: "art. 1.052, CC", p: "Se algum sócio não integralizou (remisso), todos respondem perante credores pelo valor faltante." },
  { id: "est-sociedades-limitadas-02", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "A limitada pode ter um único sócio e qual nome empresarial adota?", v: "Sim, pode ser constituída por uma ou mais pessoas. Pode adotar firma ou denominação, sempre com a palavra 'limitada' (ou 'Ltda.') ao final.", b: null, p: "Omitir 'limitada' no nome pode levar à responsabilidade pessoal de quem usou o nome." },
  { id: "est-sociedades-limitadas-03", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Com o que o sócio pode contribuir para o capital da limitada?", v: "Com dinheiro ou bens; não se admite contribuição que consista apenas em prestação de serviços.", b: null },
  { id: "est-sociedades-limitadas-04", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Qual a regra da cessão de quotas na limitada, no silêncio do contrato?", v: "Entre sócios, a cessão é livre. Para terceiros estranhos, é possível desde que não haja oposição de titulares de mais de 1/4 do capital social.", b: "art. 1.057, CC" },
  { id: "est-sociedades-limitadas-05", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Quais os órgãos da limitada e como deliberam os sócios?", v: "Administração (obrigatória, por sócio ou não sócio) e conselho fiscal (facultativo, com 3 ou mais membros). Com até 10 sócios a deliberação pode ser em reunião; acima de 10, é obrigatória a assembleia.", b: null },
  { id: "est-sociedades-limitadas-06", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Qual o quórum para designar administrador não sócio na limitada?", v: "No mínimo 2/3 dos sócios enquanto o capital não estiver integralizado; mais da metade do capital social depois de integralizado.", b: null },
  { id: "est-sociedades-limitadas-07", d: "Direito Empresarial", r: "E", t: "Sociedades limitadas", f: "Que teoria de desconsideração da personalidade jurídica o Código Civil adota e quais os requisitos?", v: "A teoria maior: exige abuso da personalidade, por desvio de finalidade ou confusão patrimonial, decretado pelo juiz a pedido da parte ou do MP. Atinge só sócios ou administradores beneficiados direta ou indiretamente pelo abuso.", b: "art. 50, CC" },
  { id: "est-tratados-internacionais-01", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "Como a Convenção de Viena de 1969 define tratado?", v: "Acordo internacional escrito entre Estados, regido pelo Direito Internacional, em um ou mais instrumentos conexos, qualquer que seja sua denominação.", b: "art. 2º, 1, a, Convenção de Viena de 1969", p: "A definição da Convenção de 1969 abrange apenas acordos entre Estados, não 'Estados e/ou organizações internacionais'." },
  { id: "est-tratados-internacionais-02", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "Como se adota o texto de um tratado numa conferência internacional?", v: "Por maioria de 2/3 dos Estados presentes e votantes, salvo se, pela mesma maioria, decidirem outra regra. Fora de conferência, exige-se o consentimento de todos os participantes.", b: "art. 9º, Convenção de Viena de 1969" },
  { id: "est-tratados-internacionais-03", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "Como funciona a ratificação de tratado no Brasil?", v: "O Presidente celebra, o Congresso Nacional autoriza e o Presidente ratifica, em ato discricionário, expresso e irretratável. Depois, a promulgação por decreto e a publicação no DOU internalizam o tratado.", b: null, p: "Mesmo com aprovação do Congresso, o Presidente pode deixar de ratificar." },
  { id: "est-tratados-internacionais-04", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "O que é reserva e quando ela não é admitida?", v: "Declaração unilateral do Estado ao assinar, ratificar ou aderir, para excluir ou modificar efeitos de certas cláusulas. Não cabe se o tratado a proíbe, se só admite outras reservas ou se ela é incompatível com o objeto e a finalidade do tratado.", b: "art. 19, Convenção de Viena de 1969" },
  { id: "est-tratados-internacionais-05", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "O Estado pode invocar seu direito interno para descumprir tratado?", v: "Não. A parte não pode alegar normas internas para justificar o inadimplemento; a exceção é a violação manifesta de norma interna fundamental sobre competência para celebrar tratados.", b: "arts. 27 e 46, Convenção de Viena de 1969" },
  { id: "est-tratados-internacionais-06", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "O que acontece com tratado que conflita com norma de jus cogens?", v: "É nulo. Jus cogens é norma imperativa aceita pela comunidade internacional, que não admite derrogação e só pode ser modificada por norma posterior da mesma natureza.", b: "art. 53, Convenção de Viena de 1969", p: "A consequência é a nulidade, e não a mera suspensão da execução do tratado." },
  { id: "est-tratados-internacionais-07", d: "Direito Internacional", r: "E", t: "Tratados internacionais", f: "A denúncia de tratado pelo Brasil precisa de aprovação do Congresso?", v: "Sim. O STF (ADI 1625, 2023) decidiu que a denúncia, assim como a ratificação, depende de aprovação do Congresso Nacional.", b: null, p: "Em tratado bilateral a denúncia extingue o acordo; em multilateral, ele deixa de valer só para quem denunciou." },
  { id: "est-adocao-01", d: "ECA", r: "E", t: "Adoção", f: "Quais as principais características da adoção?", v: "É medida excepcional, personalíssima (vedada por procuração), irrevogável e plena. É constituída por sentença e produz efeitos a partir do trânsito em julgado.", b: null, p: "A adoção internacional é ainda mais excepcional, só depois de esgotada a colocação no Brasil." },
  { id: "est-adocao-02", d: "ECA", r: "E", t: "Adoção", f: "O adotante que morre durante o processo pode ter a adoção deferida?", v: "Sim, se já tiver manifestado de forma inequívoca a vontade de adotar antes da sentença. Nesse caso, os efeitos retroagem à data do óbito.", b: "art. 42, § 6º, ECA", p: "Não depende de anuência dos herdeiros, e o efeito não se conta do trânsito em julgado." },
  { id: "est-adocao-03", d: "ECA", r: "E", t: "Adoção", f: "Quais os requisitos de idade para adotar?", v: "O adotante deve ter pelo menos 18 anos e ser, no mínimo, 16 anos mais velho que o adotado.", b: null },
  { id: "est-adocao-04", d: "ECA", r: "E", t: "Adoção", f: "Quem não pode adotar?", v: "Ascendentes e irmãos do adotando, que integram a família extensa. Tutor ou curador também não pode adotar o pupilo enquanto não prestar contas e quitar o que deve.", b: null },
  { id: "est-adocao-05", d: "ECA", r: "E", t: "Adoção", f: "Quais as regras do consentimento dos pais biológicos?", v: "Só vale se dado após o nascimento, depois de orientação, e prestado ou ratificado perante o juiz. Pode ser retratado até a audiência.", b: null, p: "Consentimento dado durante a gestação não tem valor." },
  { id: "est-adocao-06", d: "ECA", r: "E", t: "Adoção", f: "Quais os prazos do estágio de convivência e do processo de adoção?", v: "Estágio de convivência: até 90 dias, prorrogável por igual período; para adotante residente fora do país, de 30 a 45 dias, prorrogável uma vez. O processo deve terminar em até 120 dias, prorrogáveis por decisão fundamentada.", b: null },
  { id: "est-adocao-07", d: "ECA", r: "E", t: "Adoção", f: "Quando se dispensa a prévia inscrição no cadastro de adoção?", v: "Na adoção unilateral, na feita por parente com vínculo de afinidade e afetividade e na feita por quem já tem a tutela ou guarda legal de criança com mais de 3 anos.", b: null },
  { id: "est-teoria-da-pena-01", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Qual teoria das funções da pena o Código Penal adota?", v: "A teoria unitária (eclética), que soma retribuição e prevenção: prevenção geral negativa na cominação, prevenção geral positiva e retribuição na dosimetria, prevenção especial na execução.", b: "art. 59, CP" },
  { id: "est-teoria-da-pena-02", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Qual o limite de cumprimento de pena e o que ocorre com nova condenação por fato posterior?", v: "O limite é 40 anos. Se houver nova condenação por fato posterior, soma-se o saldo restante à nova pena e unifica-se de novo em 40, desprezando o tempo já cumprido.", b: "art. 75, CP", p: "Benefícios como a progressão são calculados sobre a pena total aplicada, não sobre os 40 anos (Súmula 715 STF)." },
  { id: "est-teoria-da-pena-03", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Quando se configura a reincidência e quando ela deixa de existir?", v: "Quando o agente comete novo crime após o trânsito em julgado de condenação anterior, no Brasil ou no exterior. Desaparece se passarem mais de 5 anos entre o fim do cumprimento ou a extinção da pena e o novo crime.", b: "arts. 63 e 64, CP", p: "Crimes militares próprios e crimes políticos não geram reincidência." },
  { id: "est-teoria-da-pena-04", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "A mesma condenação pode servir como reincidência e como maus antecedentes?", v: "Não, seria bis in idem. Mas, havendo duas condenações anteriores, uma pode agravar como reincidência e a outra pesar como maus antecedentes.", b: "Súmula 241 STJ" },
  { id: "est-teoria-da-pena-05", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "A confissão espontânea atenua a pena mesmo que não seja usada pelo juiz?", v: "Sim, em qualquer fase (policial ou judicial), ainda que não fundamente a condenação. A confissão qualificada (com alegação de excludente) também atenua.", b: "Súmula 545 STJ" },
  { id: "est-teoria-da-pena-06", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Qual a diferença entre as atenuantes do art. 65 e a atenuante genérica do art. 66 do CP?", v: "As do art. 65 são obrigatórias quando presentes. A do art. 66 é inominada: o juiz pode reduzir a pena por circunstância relevante não prevista em lei, e costuma ser ligada à teoria da coculpabilidade.", b: "art. 66, CP" },
  { id: "est-teoria-da-pena-07", d: "Direito Penal", r: "E", t: "Teoria da pena", f: "Em que prazo se paga a multa e quem a executa?", v: "Em até 10 dias após o trânsito em julgado, podendo ser parcelada. Se não for paga, é executada perante o juízo da execução penal (pelo MP), como dívida de valor.", b: "arts. 50 e 51, CP", p: "Não cabe habeas corpus contra condenação apenas a multa (Súmula 693 STF)." },
  { id: "est-responsabilidade-civil-d-01", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Qual teoria fundamenta, em regra, a responsabilidade civil do Estado e o que a vítima precisa provar?", v: "A teoria do risco administrativo: responsabilidade objetiva das pessoas de direito público e das privadas prestadoras de serviço público. Basta provar conduta, dano e nexo causal, sem discutir dolo ou culpa do agente.", b: "art. 37, § 6º, CF", p: "Mesmo ato lícito pode gerar dever de indenizar, mas só se o dano for anormal e específico." },
  { id: "est-responsabilidade-civil-d-02", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Qual a diferença entre risco administrativo e risco integral? Dê exemplo de risco integral.", v: "No risco administrativo o Estado pode afastar ou reduzir sua responsabilidade com excludentes (caso fortuito, força maior, culpa exclusiva da vítima ou de terceiro). No risco integral não há excludentes; a doutrina majoritária o aplica ao dano nuclear.", b: "art. 21, XXIII, d, CF" },
  { id: "est-responsabilidade-civil-d-03", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Como fica a responsabilidade do Estado por omissão?", v: "Pela visão tradicional, a omissão genérica gera responsabilidade subjetiva (culpa administrativa: é preciso provar dolo ou culpa). Na omissão específica, quando o Estado está na posição de garante (ex.: pessoa sob sua custódia), o STF aplica responsabilidade objetiva.", b: null },
  { id: "est-responsabilidade-civil-d-04", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "O Estado responde pela morte de detento, inclusive por suicídio?", v: "Em regra sim, objetivamente, por descumprir o dever específico de proteção do preso. Mas, por ser risco administrativo, o Estado pode provar excludente e afastar o dever de indenizar; a mesma lógica vale para alunos sob guarda em escola pública.", b: "art. 5º, XLIX, CF", p: "Nem todo suicídio de preso gera indenização: é preciso que o Estado tenha falhado no dever de proteção." },
  { id: "est-responsabilidade-civil-d-05", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "O Estado responde por crime cometido por preso foragido?", v: "Não, se não houver nexo causal direto entre o momento da fuga e o crime praticado (Tema 362 do STF). O dano causado pelo terceiro precisa ter ligação estreita com a omissão estatal.", b: "art. 37, § 6º, CF" },
  { id: "est-responsabilidade-civil-d-06", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "A vítima pode processar diretamente o servidor que causou o dano?", v: "Não. Pela tese da dupla garantia (STF, repercussão geral), a ação é proposta contra o Estado ou a prestadora de serviço público; o agente é parte ilegítima e só responde em regresso, se tiver agido com dolo ou culpa (responsabilidade subjetiva).", b: "art. 37, § 6º, CF" },
  { id: "est-responsabilidade-civil-d-07", d: "Direito Administrativo", r: "E", t: "Responsabilidade civil do Estado", f: "Concessionária de serviço público responde por furto e roubo ocorridos em suas dependências?", v: "Para o STF, a prestadora responde por furto em suas dependências (falha no dever de vigilância). Para o STJ, a concessionária de rodovia não responde por roubo e sequestro em estabelecimento de apoio ao usuário: roubo armado é fato de terceiro equiparado a força maior.", b: null, p: "A prestadora responde objetivamente tanto perante usuários quanto não usuários do serviço." },
  { id: "est-oferta-e-publicidade-pra-01", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Qual o efeito da oferta ou publicidade suficientemente precisa?", v: "Obriga o fornecedor que a veicula ou dela se aproveita e passa a integrar o contrato que vier a ser celebrado. O fornecedor responde solidariamente pelos atos de prepostos e representantes autônomos.", b: "art. 30, CDC" },
  { id: "est-oferta-e-publicidade-pra-02", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Se o fornecedor se recusar a cumprir a oferta, o que o consumidor pode fazer?", v: "À sua livre escolha: exigir o cumprimento forçado nos termos da oferta, aceitar outro produto ou serviço equivalente, ou rescindir o contrato com devolução do que pagou, corrigido, mais perdas e danos.", b: "art. 35, CDC" },
  { id: "est-oferta-e-publicidade-pra-03", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Diferencie publicidade enganosa de publicidade abusiva.", v: "Enganosa é a total ou parcialmente falsa, capaz de induzir o consumidor em erro sobre o produto ou serviço (natureza, qualidade, preço etc.). Abusiva é a que discrimina, incita violência ou explora medo ou superstição. Ambas são proibidas.", b: "art. 37, CDC", p: "Há publicidade enganosa por omissão quando se deixa de informar dado essencial do produto ou serviço (art. 37, § 3º)." },
  { id: "est-oferta-e-publicidade-pra-04", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "Quem tem o ônus de provar a veracidade da informação publicitária?", v: "Quem patrocina a publicidade, não o consumidor.", b: null },
  { id: "est-oferta-e-publicidade-pra-05", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "O envio de cartão de crédito sem solicitação do consumidor é permitido?", v: "Não. É prática abusiva, gera dano moral indenizável mesmo sem prejuízo comprovado e sujeita o banco a multa administrativa (que não vai para o consumidor). Quem foi exposto à prática é consumidor por equiparação.", b: "Súmula 532 STJ", p: "O rol de práticas abusivas do CDC é meramente exemplificativo." },
  { id: "est-oferta-e-publicidade-pra-06", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "O que deve constar do orçamento prévio e qual sua validade?", v: "Valor da mão de obra, dos materiais e equipamentos, condições de pagamento e datas de início e término do serviço. Vale por 10 dias, contados do recebimento pelo consumidor; executar serviço sem orçamento e autorização expressa é prática abusiva.", b: null },
  { id: "est-oferta-e-publicidade-pra-07", d: "Direito do Consumidor", r: "E", t: "Oferta e publicidade; práticas abusivas; bancos de dados", f: "O banco pode debitar da conta-corrente o pagamento mínimo da fatura do cartão em atraso?", v: "Só se houver cláusula expressa, clara e destacada no contrato autorizando o débito; nesse caso, o STJ entende que a cláusula não é abusiva. Conta-corrente e cartão de crédito são contratos distintos.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-01", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quando e como foi aprovada a Declaração Universal dos Direitos Humanos?", v: "Em 10 de dezembro de 1948, em Paris, com 48 votos a favor, 8 abstenções (entre elas a URSS e países do bloco socialista, Arábia Saudita e África do Sul) e nenhum voto contrário. O Brasil votou a favor.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-02", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Como está estruturada a DUDH e o que diz seu artigo 1º?", v: "Preâmbulo mais 30 artigos com direitos civis e políticos, econômicos, sociais e culturais e cláusulas de deveres. O art. 1º afirma que todos nascem livres e iguais em dignidade e direitos, dotados de razão e consciência, e devem agir com fraternidade.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-03", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quais proibições da DUDH são consideradas absolutas?", v: "A proibição da escravidão e da servidão e a da tortura e de tratamentos cruéis, desumanos ou degradantes (arts. 4º e 5º). São normas de jus cogens, que não admitem derrogação nem em guerra ou emergência.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-04", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Por que existem dois Pactos de 1966 e o que formam junto com a DUDH?", v: "A Guerra Fria levou à separação: direitos civis e políticos (aplicação imediata, PIDCP) e econômicos, sociais e culturais (realização progressiva, PIDESC). Com a DUDH formam a Carta Internacional de Direitos Humanos.", b: null, p: "Apesar da divisão, a leitura atual é de indivisibilidade e interdependência, sem hierarquia entre os direitos." },
  { id: "est-dudh-pidcp-e-pidesc-05", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quais são os Protocolos Facultativos ao PIDCP?", v: "O Primeiro cria o direito de petição individual ao Comitê de Direitos Humanos; o Segundo visa abolir a pena de morte, admitindo reserva só em tempo de guerra para crimes militares gravíssimos. O PIDCP foi incorporado no Brasil pelo Decreto 592/1992.", b: null },
  { id: "est-dudh-pidcp-e-pidesc-06", d: "Direitos Humanos", r: "E", t: "DUDH, PIDCP e PIDESC", f: "Quando o PIDCP permite derrogar direitos e quais são inderrogáveis?", v: "Em emergência pública que ameace a existência da nação, proclamada oficialmente, com medidas estritamente necessárias, sem discriminação e com notificação aos demais Estados. São inderrogáveis: vida, proibição de tortura, de escravidão e servidão, de prisão por dívida civil, legalidade e irretroatividade penal, personalidade jurídica e liberdade de pensamento, consciência e religião.", b: null },
  { id: "est-especies-de-erro-essenci-01", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Quais as consequências do erro de tipo incriminador?", v: "Sempre exclui o dolo. Se inevitável (escusável), exclui também a culpa e o fato é atípico; se evitável, o agente responde pela forma culposa, se houver previsão legal.", b: "art. 20, CP", p: "Erro sobre a idade da vítima no estupro de vulnerável é erro de tipo: como não existe forma culposa, não há crime." },
  { id: "est-especies-de-erro-essenci-02", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "O que é erro de tipo permissivo (descriminante putativa) e qual sua consequência?", v: "Erro sobre a situação de fato de uma excludente de ilicitude (ex.: legítima defesa putativa). Pela teoria limitada da culpabilidade, se inevitável isenta de pena; se evitável, o agente responde por crime culposo, se previsto.", b: "art. 20, § 1º, CP" },
  { id: "est-especies-de-erro-essenci-03", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "O que é culpa imprópria?", v: "É a punição a título de culpa no erro de tipo permissivo evitável: o agente age com dolo, mas o dolo é afastado e ele responde pela forma culposa.", b: "art. 20, § 1º, CP", p: "É a única hipótese em que se admite tentativa de crime culposo." },
  { id: "est-especies-de-erro-essenci-04", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Quais as consequências do erro de proibição?", v: "Recai sobre a consciência da ilicitude (elemento da culpabilidade). Se inevitável, isenta de pena; se evitável, reduz a pena de 1/6 a 1/3. O desconhecimento da lei, em si, é inescusável.", b: "art. 21, CP" },
  { id: "est-especies-de-erro-essenci-05", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Erro sobre a pessoa e erro na execução (aberratio ictus): qual a diferença e a consequência comum?", v: "No erro sobre a pessoa o agente confunde a identidade da vítima; no aberratio ictus ele erra o alvo por falha nos meios de execução. Em ambos responde como se tivesse atingido quem pretendia, considerando as qualidades dessa pessoa.", b: "art. 20, § 3º, e art. 73, CP", p: "Se atingir também a vítima pretendida, aplica-se o concurso formal (art. 70)." },
  { id: "est-especies-de-erro-essenci-06", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "O que é aberratio criminis e quando ela não se aplica?", v: "Por erro na execução, sobrevém resultado diverso do pretendido (ex.: quer danificar coisa e mata alguém): responde só pelo resultado culposo, se previsto. Não se aplica no caso inverso (mira pessoa e atinge coisa), pois não há dano culposo: responde pela tentativa contra a pessoa.", b: "art. 74, CP" },
  { id: "est-especies-de-erro-essenci-07", d: "Direito Penal", r: "E", t: "Espécies de erro: essenciais e acidentais", f: "Quem responde quando o erro é provocado por terceiro?", v: "Responde pelo crime o terceiro que determinou o erro; quem agiu enganado, sem culpa, não responde.", b: "art. 20, § 2º, CP" },
  { id: "est-ato-infracional-e-medida-01", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "O que é ato infracional e que medidas cabem para criança e para adolescente?", v: "É a conduta descrita como crime ou contravenção penal praticada por criança ou adolescente. À criança só se aplicam medidas de proteção; ao adolescente, medidas socioeducativas, que podem ser cumuladas com medidas de proteção.", b: null, p: "Considera-se praticado o ato no momento da ação ou omissão (teoria da atividade), ainda que o resultado venha depois." },
  { id: "est-ato-infracional-e-medida-02", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Quais os requisitos e o prazo da internação provisória?", v: "Decisão judicial fundamentada, com indícios de autoria e materialidade, pelo prazo máximo e improrrogável de 45 dias.", b: null, p: "Não pode ser decretada só com base na gravidade abstrata do ato." },
  { id: "est-ato-infracional-e-medida-03", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Em quais hipóteses cabe a medida de internação?", v: "Só em três: ato infracional com grave ameaça ou violência a pessoa; reiteração em outras infrações graves; ou descumprimento reiterado e injustificável de medida anterior. No último caso, a internação-sanção dura no máximo 3 meses.", b: "art. 122, ECA" },
  { id: "est-ato-infracional-e-medida-04", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "O que se exige para aplicar a advertência?", v: "Basta prova da materialidade e indícios de autoria; não é necessária prova plena da autoria. É a medida mais branda, uma admoestação verbal feita pelo juiz.", b: null, p: "Na remissão nem sequer se exige prova de autoria e materialidade." },
  { id: "est-ato-infracional-e-medida-05", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Quais os limites da prestação de serviços à comunidade?", v: "Tarefas gratuitas de interesse geral por no máximo 6 meses e até 8 horas semanais, inclusive em sábados, domingos e feriados, sem prejudicar a escola ou o trabalho.", b: null },
  { id: "est-ato-infracional-e-medida-06", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Qual a duração da liberdade assistida e até que idade as medidas podem ser cumpridas?", v: "A liberdade assistida dura no mínimo 6 meses; sem máximo na lei, o STJ aplica o teto de 3 anos da internação. Internação, semiliberdade e liberdade assistida podem ser cumpridas até os 21 anos.", b: null },
  { id: "est-ato-infracional-e-medida-07", d: "ECA", r: "E", t: "Ato infracional e medidas socioeducativas", f: "Como funciona a remissão no ECA?", v: "É perdão ou abrandamento que pode partir do MP (antes do processo, como exclusão, homologada pelo juiz) ou do juiz (no curso do processo, como suspensão ou extinção). Medida aplicada junto com a remissão exige concordância do adolescente e do defensor.", b: null },
  { id: "est-sistema-juridico-01", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Quais as principais diferenças entre direito e moral?", v: "O direito é heterônomo, bilateral (cria relação de direitos e deveres) e tem sanção externa e institucionalizada, com uso legítimo da força. A moral é autônoma, unilateral e sua sanção é interna ou social, sem organização institucional.", b: null, p: "A norma moral é só imperativa; a jurídica é imperativo-atributiva, pois dá a alguém o poder de exigir seu cumprimento." },
  { id: "est-sistema-juridico-02", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Qual a diferença entre o princípio da causalidade e o da imputação?", v: "As ciências naturais operam por causalidade (se A, então B: chove, então molha). A ciência jurídica atua no dever-ser pela imputação (se A, então deve ser B: quem rouba deve ser punido).", b: null },
  { id: "est-sistema-juridico-03", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "O que é lacuna ideológica e o que é lacuna ontológica?", v: "Ideológica (axiológica): existe norma, mas falta uma solução justa ou satisfatória para o caso. Ontológica: existe norma, mas ela perdeu eficácia social por dissociação com a realidade.", b: null, p: "Lacuna ideológica não é ausência de lei; a ausência de norma é a lacuna normativa." },
  { id: "est-sistema-juridico-04", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Quais os critérios para resolver antinomias e qual prevalece?", v: "Hierárquico (norma superior), cronológico (norma posterior) e especialidade (norma especial). O hierárquico prevalece sobre todos e a especialidade sobre o cronológico.", b: null, p: "Só há antinomia real se as normas forem absolutamente incompatíveis; se a interpretação as conciliar, os critérios não entram." },
  { id: "est-sistema-juridico-05", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Diferencie fonte formal de fonte material do direito.", v: "Fonte formal é a forma de manifestação do direito (lei, costumes, princípios gerais). Fonte material são os fatores políticos, econômicos e ideológicos que condicionam o conteúdo das normas.", b: null },
  { id: "est-sistema-juridico-06", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Quais os requisitos para um comportamento ser costume jurídico?", v: "Objetivo: prática constante, uniforme e reiterada no tempo. Subjetivo: crença na obrigatoriedade da conduta (opinio necessitatis).", b: null },
  { id: "est-sistema-juridico-07", d: "Filosofia do Direito", r: "E", t: "Sistema jurídico", f: "Tecnicamente, o que é jurisprudência?", v: "Conjunto de decisões judiciais reiteradas, constantes e harmônicas sobre casos semelhantes, formando orientação geral. Uma decisão isolada não é jurisprudência.", b: null },
  { id: "est-partes-e-procuradores-tu-01", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "O que é jus postulandi e onde ele não se aplica?", v: "É a possibilidade de empregado e empregador reclamarem pessoalmente, sem advogado, até o final. Limita-se às Varas e aos TRTs: não alcança ação rescisória, ação cautelar, mandado de segurança e recursos de competência do TST.", b: "art. 791, CLT; Súmula 425 TST" },
  { id: "est-partes-e-procuradores-tu-02", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Quem ajuíza a reclamação trabalhista do menor de 18 anos?", v: "Seus representantes legais; na falta deles, a Procuradoria da Justiça do Trabalho, o sindicato, o MP estadual ou curador nomeado em juízo.", b: "art. 793, CLT", p: "A ordem é sucessiva: só se passa ao próximo na falta do anterior." },
  { id: "est-partes-e-procuradores-tu-03", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Como o empregador e o empregado podem ser representados na audiência?", v: "O empregador pode ser substituído por gerente ou preposto que conheça os fatos, cujas declarações o obrigam. O empregado, por doença ou outro motivo poderoso comprovado, pode ser representado por colega da mesma profissão ou pelo sindicato.", b: "art. 843, §§ 1º e 2º, CLT", p: "O preposto não precisa ser empregado." },
  { id: "est-partes-e-procuradores-tu-04", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "O que é mandato tácito e quais seus limites?", v: "Constituição de advogado por simples registro em ata de audiência, a pedido verbal do advogado e com anuência da parte. Dá apenas poderes gerais para o foro: não permite atos que exigem poderes especiais (transigir, desistir, receber, dar quitação etc.).", b: "art. 791, § 3º, CLT", p: "É inválido o substabelecimento feito por advogado com mandato tácito (OJ 200 SDI-1)." },
  { id: "est-partes-e-procuradores-tu-05", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Recurso assinado por advogado sem procuração nos autos é conhecido?", v: "Não, salvo mandato tácito. Excepcionalmente, o advogado pode exibir a procuração em 5 dias após a interposição, sem intimação, prorrogáveis por igual período. Se a procuração já está nos autos mas tem defeito, o relator intima para sanar em 5 dias.", b: "Súmula 383 TST" },
  { id: "est-partes-e-procuradores-tu-06", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Procuradores de entes públicos precisam juntar procuração?", v: "Não. União, Estados, DF, Municípios, autarquias e fundações públicas, representados por seus procuradores, dispensam mandato e prova de nomeação, mas o signatário deve ao menos declarar que exerce o cargo de procurador.", b: "Súmula 436 TST", p: "Indicar só o número de inscrição na OAB não basta." },
  { id: "est-partes-e-procuradores-tu-07", d: "Direito Processual do Trabalho", r: "E", t: "Partes e procuradores; tutela provisória", f: "Litisconsortes com advogados diferentes têm prazo em dobro no processo do trabalho?", v: "Não. O TST considera o prazo em dobro do CPC incompatível com a celeridade do processo do trabalho.", b: "OJ 310 SDI-1 TST" },
  { id: "est-licitacoes-01", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Empresas públicas e sociedades de economia mista licitam pela Lei 14.133/2021?", v: "Não. Estatais e suas subsidiárias seguem a Lei 13.303/2016; a Lei 14.133/2021 vale para a administração direta, autárquica e fundacional de todos os entes.", b: "art. 1º, § 1º, Lei 14.133/2021", p: "A exceção do art. 178 (crimes) é a única parte da nova lei que alcança as estatais." },
  { id: "est-licitacoes-02", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Contratar cantor consagrado pela crítica ou pelo público, via empresário exclusivo, exige licitação?", v: "Não. É inexigibilidade, porque a competição é inviável; não se exige comparar orçamentos de outros artistas.", b: "art. 74, II, Lei 14.133/2021", p: "Não é dispensa (que depende de hipótese legal com competição possível), e o valor do cachê não muda a natureza da contratação." },
  { id: "est-licitacoes-03", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Na Lei 14.133/2021, compra ou locação de imóvel cujas instalações e localização tornem necessária sua escolha é dispensa ou inexigibilidade?", v: "Inexigibilidade. Na lei antiga era dispensa; a nova lei acolheu a visão doutrinária de que não há competição possível.", b: null },
  { id: "est-licitacoes-04", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Qual a ordem das fases da licitação na Lei 14.133/2021?", v: "Preparatória, divulgação do edital, propostas e lances, julgamento, habilitação, recursal e homologação. Em regra, o julgamento vem antes da habilitação.", b: "art. 17, Lei 14.133/2021" },
  { id: "est-licitacoes-05", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Como funciona o recurso contra o julgamento das propostas?", v: "A intenção de recorrer deve ser manifestada logo, mas as razões (3 dias úteis) só correm da intimação ou da ata de habilitação/inabilitação, pois os recursos são apreciados numa fase única.", b: "art. 165, I e § 1º, Lei 14.133/2021", p: "Não há efeito suspensivo automático nem 'pedido de reconsideração' como via própria contra o julgamento." },
  { id: "est-licitacoes-06", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Qual a vigência da ata de registro de preços e ela obriga a Administração a contratar?", v: "Vigora por 1 ano, prorrogável por igual período se o preço continuar vantajoso. Gera compromisso de fornecimento para o fornecedor, mas não obriga a Administração a contratar.", b: "arts. 83 e 84, Lei 14.133/2021", p: "Registro de preços não é modalidade de licitação: é procedimento auxiliar, feito por pregão, concorrência ou contratação direta." },
  { id: "est-licitacoes-07", d: "Direito Administrativo", r: "E", t: "Licitações", f: "Quem responde por contratação direta indevida feita com dolo, fraude ou erro grosseiro?", v: "O contratado e o agente público responsável respondem solidariamente pelo dano ao erário, sem prejuízo de outras sanções.", b: "art. 73, Lei 14.133/2021" },
  { id: "est-orcamento-publico-leis-o-01", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Quem tem a iniciativa e qual a espécie normativa do PPA, da LDO e da LOA?", v: "Iniciativa privativa do Chefe do Executivo, sem substituição nem em caso de omissão; aprovação por lei ordinária do Legislativo, por maioria simples.", b: "art. 165, CF", p: "Medida provisória não pode aprovar lei orçamentária, e lei complementar não é exigida." },
  { id: "est-orcamento-publico-leis-o-02", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Investimento cuja execução ultrapasse um exercício pode começar sem estar no PPA?", v: "Não. Exige prévia inclusão no plano plurianual ou lei que autorize a inclusão, sob pena de crime de responsabilidade.", b: "art. 167, § 1º, CF" },
  { id: "est-orcamento-publico-leis-o-03", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Quais os prazos de envio e devolução do projeto de LDO, enquanto não vem a lei complementar?", v: "Envio até 15 de abril (8 meses e meio antes do fim do exercício) e devolução para sanção até o fim do primeiro período da sessão legislativa (17 de julho).", b: "art. 35, § 2º, II, ADCT", p: "A sessão legislativa não é interrompida sem a aprovação do projeto de LDO (art. 57, § 2º, CF)." },
  { id: "est-orcamento-publico-leis-o-04", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "O que diz o princípio da exclusividade da LOA e quais suas exceções?", v: "A LOA não pode conter matéria estranha à previsão de receita e fixação de despesa; pode, porém, autorizar abertura de créditos suplementares e contratação de operações de crédito, inclusive por antecipação de receita.", b: "art. 165, § 8º, CF" },
  { id: "est-orcamento-publico-leis-o-05", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Diferencie crédito suplementar, especial e extraordinário.", v: "Suplementar reforça dotação já existente; especial cria dotação para despesa não prevista; extraordinário atende despesa imprevisível e urgente (guerra, comoção interna ou calamidade pública).", b: "art. 41, Lei 4.320/1964", p: "Só o suplementar pode ser autorizado previamente na própria LOA; o especial exige sempre lei específica." },
  { id: "est-orcamento-publico-leis-o-06", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Como é aberto o crédito extraordinário e quando créditos especiais e extraordinários vigem no ano seguinte?", v: "O extraordinário pode ser aberto por medida provisória na União (decreto nos demais entes). Especiais e extraordinários autorizados nos últimos 4 meses do exercício podem ser reabertos, nos limites do saldo, no exercício seguinte.", b: "art. 167, §§ 2º e 3º, CF" },
  { id: "est-orcamento-publico-leis-o-07", d: "Direito Financeiro", r: "E", t: "Orçamento público: leis orçamentárias", f: "Se o Executivo não envia o projeto de LOA no prazo, o que o Legislativo faz?", v: "Não pode iniciar o projeto nem receber propostas parciais diretamente dos outros Poderes; considera como proposta a lei de orçamento vigente.", b: "art. 32, Lei 4.320/1964" },
  { id: "est-eia-rima-licenciamento-e-01", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quais são as três licenças do licenciamento trifásico e o que cada uma autoriza?", v: "Licença prévia: aprova localização e concepção e atesta a viabilidade ambiental; licença de instalação: autoriza a implantação conforme os projetos aprovados; licença de operação: autoriza o funcionamento após verificar o cumprimento das anteriores.", b: "art. 8º, Resolução Conama 237/1997" },
  { id: "est-eia-rima-licenciamento-e-02", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Licença ambiental válida pode ser modificada, suspensa ou cancelada?", v: "Sim, por decisão motivada, em caso de violação de condicionantes ou normas legais, omissão ou falsa informação relevante, ou superveniência de graves riscos ambientais e de saúde.", b: "art. 19, Resolução Conama 237/1997", p: "Lei nova mais protetiva não anula automaticamente a licença; o órgão precisa decidir de forma motivada." },
  { id: "est-eia-rima-licenciamento-e-03", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quando o EIA/RIMA é obrigatório e qual a diferença entre EIA e RIMA?", v: "Para obra ou atividade potencialmente causadora de significativa degradação ambiental. O EIA é o estudo técnico completo; o RIMA é sua síntese em linguagem acessível ao público — não existe RIMA sem EIA.", b: "art. 225, § 1º, IV, CF" },
  { id: "est-eia-rima-licenciamento-e-04", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quem pode pedir audiência pública no EIA/RIMA e o que acontece se ela não for feita?", v: "Órgão ambiental, Ministério Público, entidade civil ou 50 ou mais cidadãos, em prazo mínimo de 45 dias do edital. Se pedida e não realizada, a licença é inválida.", b: "art. 2º, Resolução Conama 9/1987", p: "O órgão não fica vinculado ao que se delibera na audiência, mas deve considerar o material produzido." },
  { id: "est-eia-rima-licenciamento-e-05", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Quem elabora e custeia o estudo de impacto ambiental?", v: "Profissionais legalmente habilitados, às custas do empreendedor; ao órgão licenciador cabe apenas analisá-lo.", b: "art. 11, Resolução Conama 237/1997" },
  { id: "est-eia-rima-licenciamento-e-06", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "O que ocorre se o órgão licenciador perde o prazo sem emitir a licença?", v: "Não há licença tácita nem autorização para a atividade; instaura-se a competência supletiva de outro ente (ex.: a União no lugar do Estado).", b: "art. 14, § 3º, LC 140/2011", p: "Não confundir com atuação subsidiária, que é apoio pedido pelo próprio ente originalmente competente." },
  { id: "est-eia-rima-licenciamento-e-07", d: "Direito Ambiental", r: "E", t: "EIA/RIMA, licenciamento e compensação ambiental", f: "Outro ente pode autuar empreendimento licenciado por um Estado?", v: "Sim, a fiscalização é atribuição comum, mas, havendo autos dos dois, prevalece o lavrado pelo órgão que licenciou.", b: "art. 17, LC 140/2011" },
  { id: "est-falencia-01", d: "Direito Empresarial", r: "E", t: "Falência", f: "Qual o juízo competente para decretar a falência?", v: "O do local do principal estabelecimento do devedor (ou da filial de empresa com sede fora do Brasil), entendido como o local de maior volume de negócios.", b: "art. 3º, Lei 11.101/2005", p: "Não é o juízo da sede estatutária nem de qualquer filial." },
  { id: "est-falencia-02", d: "Direito Empresarial", r: "E", t: "Falência", f: "Quem pode requerer a falência do devedor?", v: "O próprio devedor (autofalência), o cônjuge sobrevivente, herdeiro ou inventariante, o sócio ou acionista e qualquer credor.", b: "art. 97, Lei 11.101/2005", p: "Credor domiciliado no exterior deve prestar caução; credor empresário precisa estar regularmente registrado." },
  { id: "est-falencia-03", d: "Direito Empresarial", r: "E", t: "Falência", f: "Quais entidades não se sujeitam à Lei de Falências?", v: "Empresas públicas, sociedades de economia mista, instituições financeiras, cooperativas de crédito, consórcios, previdência complementar, operadoras de plano de saúde, seguradoras e sociedades de capitalização.", b: "art. 2º, Lei 11.101/2005" },
  { id: "est-falencia-04", d: "Direito Empresarial", r: "E", t: "Falência", f: "Quais as hipóteses de insolvência que autorizam a falência?", v: "Impontualidade sem relevante razão em títulos executivos protestados acima de 40 salários mínimos; execução frustrada (não paga, não deposita nem nomeia bens), sem valor mínimo; ou prática de atos de falência.", b: "art. 94, Lei 11.101/2005" },
  { id: "est-falencia-05", d: "Direito Empresarial", r: "E", t: "Falência", f: "Qual o prazo de defesa do devedor e o que é o depósito elisivo?", v: "10 dias para contestar. Nos pedidos por impontualidade ou execução frustrada, pode depositar o total do crédito com correção, juros e honorários, e a falência não será decretada.", b: "art. 98, Lei 11.101/2005", p: "O depósito não apenas suspende o processo: impede a decretação da quebra." },
  { id: "est-falencia-06", d: "Direito Empresarial", r: "E", t: "Falência", f: "Qual recurso cabe contra a decisão que decreta a falência e contra a que a julga improcedente?", v: "Da decretação cabe agravo; da sentença de improcedência cabe apelação.", b: "art. 100, Lei 11.101/2005" },
  { id: "est-falencia-07", d: "Direito Empresarial", r: "E", t: "Falência", f: "Tributo com fato gerador posterior à decretação da falência prefere ao crédito com garantia real?", v: "Sim. É crédito extraconcursal, pago antes dos concursais, entre os quais está o crédito com garantia real.", b: "arts. 83 e 84, Lei 11.101/2005", p: "Crédito trabalhista concursal é limitado a 150 salários mínimos por credor; o trabalhista surgido após a falência é extraconcursal e não tem esse teto." },
  { id: "est-responsabilidade-do-forn-01", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Qual a diferença entre fato e vício do produto ou serviço?", v: "Fato é o acidente de consumo causado por defeito, que atinge a segurança do consumidor; vício é a inadequação de qualidade ou quantidade que torna o produto impróprio ou lhe reduz o valor, sem acidente.", b: null },
  { id: "est-responsabilidade-do-forn-02", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Como responde o fabricante pelo fato do produto e quando se exime?", v: "Responde objetivamente, sem culpa. Só se exime provando que não colocou o produto no mercado, que o defeito não existe ou culpa exclusiva do consumidor ou de terceiro.", b: "art. 12, caput e § 3º, CDC", p: "Produto que oferece a segurança que dele se espera (ex.: airbag que não abre em colisão traseira) não é defeituoso." },
  { id: "est-responsabilidade-do-forn-03", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Quando o comerciante responde pelo fato do produto?", v: "Só de forma subsidiária: quando fabricante, produtor, construtor ou importador não puderem ser identificados, quando o produto vier sem identificação clara deles ou quando não conservar bem produtos perecíveis.", b: "art. 13, CDC", p: "No fato do serviço não há essa exceção: todos os fornecedores da cadeia respondem solidariamente." },
  { id: "est-responsabilidade-do-forn-04", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "Como respondem os profissionais liberais pelo fato do serviço?", v: "Mediante verificação de culpa (responsabilidade subjetiva), exceção à regra objetiva do CDC.", b: null },
  { id: "est-responsabilidade-do-forn-05", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "No vício de qualidade do produto, qual o prazo do fornecedor e quais as opções do consumidor?", v: "O fornecedor tem 30 dias para sanar. Não sanado, o consumidor escolhe: substituição, restituição atualizada da quantia (com perdas e danos) ou abatimento do preço.", b: "art. 18, § 1º, CDC", p: "O consumidor pode exigir as opções de imediato se o produto for essencial ou se a troca de partes comprometer qualidade ou valor (§ 3º)." },
  { id: "est-responsabilidade-do-forn-06", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "No vício de quantidade, o consumidor precisa aguardar prazo para escolher a solução?", v: "Não. Pode escolher de imediato entre abatimento do preço, complementação do peso ou medida, substituição do produto ou restituição da quantia paga.", b: "art. 19, CDC", p: "A escolha é do consumidor, não do fornecedor ou de seu preposto." },
  { id: "est-responsabilidade-do-forn-07", d: "Direito do Consumidor", r: "E", t: "Responsabilidade do fornecedor", f: "A inversão do ônus da prova é automática no CDC?", v: "Não. Fica a critério do juiz quando a alegação for verossímil ou o consumidor for hipossuficiente, podendo ser negada.", b: "art. 6º, VIII, CDC" },
  { id: "est-justica-eleitoral-e-inel-01", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "A Justiça Eleitoral tem magistratura própria? Por quanto tempo servem seus juízes?", v: "Não; seus membros vêm de outros ramos do Judiciário e da advocacia. Servem por 2 anos, com no máximo uma recondução (dois biênios consecutivos).", b: null, p: "Os advogados que integram tribunais eleitorais podem continuar advogando (ADI 1.127)." },
  { id: "est-justica-eleitoral-e-inel-02", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Qual a composição mínima do TSE?", v: "7 membros: 3 ministros do STF e 2 do STJ, eleitos por voto secreto, e 2 advogados nomeados pelo Presidente da República a partir de lista de 6 indicada pelo STF.", b: "art. 119, CF", p: "Não há sabatina no Senado nem vaga para o Ministério Público; presidente e vice são do STF e o corregedor é do STJ." },
  { id: "est-justica-eleitoral-e-inel-03", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "O juiz eleitoral pode, de ofício, instaurar procedimento para multar propaganda irregular?", v: "Não. Apesar do poder de polícia, a multa por propaganda irregular depende de provocação.", b: "Súmula 18 TSE" },
  { id: "est-justica-eleitoral-e-inel-04", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Chefe do Executivo precisa se afastar do cargo para disputar a reeleição?", v: "Não. A renúncia até 6 meses antes do pleito só é exigida para concorrer a outros cargos.", b: "art. 14, § 6º, CF" },
  { id: "est-justica-eleitoral-e-inel-05", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Quem é atingido pela inelegibilidade reflexa e qual a exceção?", v: "Cônjuge e parentes até o 2º grau ou por adoção do chefe do Executivo (ou de quem o substituiu nos 6 meses anteriores), no território de sua jurisdição; não se aplica a quem já é titular de mandato e busca a reeleição.", b: "art. 14, § 7º, CF", p: "A dissolução do casamento no curso do mandato não afasta a inelegibilidade (Súmula Vinculante 18)." },
  { id: "est-justica-eleitoral-e-inel-06", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Inelegibilidade constitucional não impugnada no registro pode ser discutida após a eleição?", v: "Sim, por recurso contra a expedição de diploma, cabível para inelegibilidade constitucional ou superveniente e falta de condição de elegibilidade, em 3 dias após o último dia fixado para a diplomação.", b: "art. 262, Código Eleitoral", p: "Não cabe AIME, que se funda em abuso do poder econômico, corrupção ou fraude." },
  { id: "est-justica-eleitoral-e-inel-07", d: "Direito Eleitoral", r: "E", t: "Justiça Eleitoral e inelegibilidades", f: "Na AIJE, o que se exige para configurar o abuso de poder?", v: "Apenas a gravidade das circunstâncias do fato, não a potencialidade de alterar o resultado da eleição. A procedência gera inelegibilidade por 8 anos e cassação do registro ou diploma.", b: "art. 22, XIV e XVI, LC 64/1990" },
  { id: "est-hermeneutica-01", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "O que defendia a Escola da Exegese?", v: "Ligada ao Código Napoleônico, via o ordenamento como completo, sem lacunas reais, e reduzia o intérprete a declarar a letra da lei segundo a vontade de um legislador tido como infalível.", b: null },
  { id: "est-hermeneutica-02", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Qual a proposta da escola da livre pesquisa científica de François Gény?", v: "Admite lacunas inevitáveis e atribui ao intérprete integrá-las com liberdade entre as fontes, valorizando o costume e distinguindo o 'dado' (realidade) do 'construído' (técnica).", b: null },
  { id: "est-hermeneutica-03", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Norma clara dispensa interpretação?", v: "Não. A máxima 'interpretatio cessat in claris' é rejeitada: clareza é relativa a quem lê e o tempo altera o sentido das normas, de modo que todo texto exige interpretação.", b: null },
  { id: "est-hermeneutica-04", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "O que é interpretação autêntica e como se compara à doutrinária?", v: "Autêntica é a feita pelo próprio legislador (ex.: a lei que define pertenças) e é obrigatória; a doutrinária, privada, não vincula e vale pela força de persuasão.", b: null },
  { id: "est-hermeneutica-05", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Qual a diferença entre interpretação histórica e sociológica?", v: "A histórica busca o sentido na realidade social da época em que a norma foi editada; a sociológica considera a realidade social atual, do momento da interpretação.", b: null },
  { id: "est-hermeneutica-06", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "O que é interpretação teleológica?", v: "A que busca a finalidade da norma, orientando o juiz a atender aos fins sociais da lei e às exigências do bem comum.", b: "art. 5º, LINDB" },
  { id: "est-hermeneutica-07", d: "Filosofia do Direito", r: "E", t: "Hermenêutica", f: "Diferencie interpretação extensiva, declaratória e restritiva.", v: "Extensiva amplia o alcance porque a lei disse menos do que queria; declaratória reconhece que texto e sentido coincidem; restritiva reduz o alcance porque a lei disse mais do que queria.", b: null, p: "A modificativa vai além da extensiva: adapta a norma a situações não previstas (atualizadora) ou para resolver antinomias (corretiva)." },
  { id: "est-convencao-americana-sobr-01", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Quando o Brasil aderiu ao Pacto de San José e com que ressalva?", v: "O Pacto é de 1969, mas o Brasil só o incorporou em 1992, já fora da ditadura. Fez reserva às visitas e investigações in loco da Comissão Interamericana, que dependem de autorização expressa do governo.", b: "Decreto 678/1992" },
  { id: "est-convencao-americana-sobr-02", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Que limites a Convenção Americana impõe à pena de morte?", v: "Só cabe para os delitos mais graves, não pode voltar onde já foi abolida e não se aplica a menores de 18 anos, maiores de 70 nem a gestantes. A vida é protegida, em geral, desde a concepção.", b: "art. 4 CADH" },
  { id: "est-convencao-americana-sobr-03", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "O que a Convenção exige do sistema prisional?", v: "Tratamento digno do preso, vedação de tortura e de tratamento cruel, separação entre processados e condenados e pena voltada à reforma e readaptação social. Superlotação e más condições carcerárias violam o Pacto.", b: "art. 5 CADH" },
  { id: "est-convencao-americana-sobr-04", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Quais trabalhos não contam como trabalho forçado proibido pela Convenção?", v: "O trabalho do preso em condições normais, o serviço militar, os serviços exigidos em calamidades e as obrigações cívicas comuns. Escravidão, servidão e tráfico de pessoas são vedados.", b: "art. 6 CADH" },
  { id: "est-convencao-americana-sobr-05", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Cite garantias do acusado no processo penal previstas no Pacto de San José.", v: "Presunção de inocência, intérprete gratuito, defensor público se não puder pagar, direito de não se autoincriminar, duplo grau de jurisdição e proibição de novo processo pelos mesmos fatos após absolvição definitiva.", b: "art. 8 CADH" },
  { id: "est-convencao-americana-sobr-06", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "Onde estão os direitos econômicos, sociais e culturais no sistema interamericano?", v: "O Pacto trata sobretudo de direitos civis e políticos; os sociais foram detalhados pelo Protocolo de San Salvador (1988). O próprio Pacto já previa o compromisso de efetivação progressiva desses direitos.", b: "art. 26 CADH" },
  { id: "est-convencao-americana-sobr-07", d: "Direitos Humanos", r: "E", t: "Convenção Americana sobre Direitos Humanos", f: "O rol de motivos de discriminação vedados pela Convenção é taxativo?", v: "Não. A cláusula 'qualquer outra condição social' torna a lista exemplificativa, alcançando orientação sexual, identidade de gênero e deficiência.", b: "art. 24 CADH" },
  { id: "est-contribuicao-previdencia-01", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Qual a base de cálculo da contribuição dos segurados e qual a exceção?", v: "Em regra é o salário de contribuição, que respeita piso e teto (diferente da remuneração, base da contribuição da empresa). O segurado especial contribui sobre a receita bruta da comercialização da produção rural.", b: null },
  { id: "est-contribuicao-previdencia-02", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Qual o limite mínimo do salário de contribuição do contribuinte individual e do facultativo?", v: "O salário-mínimo mensal, independentemente de quantos dias trabalhou. Para empregado, doméstico e avulso, o piso é o da categoria ou o salário-mínimo proporcional ao tempo trabalhado.", b: null, p: "Para CI e facultativo não há proporcionalidade por dias: o mínimo é sempre o salário-mínimo mensal." },
  { id: "est-contribuicao-previdencia-03", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Incide contribuição previdenciária sobre o salário-maternidade?", v: "O STF declarou inconstitucional a contribuição a cargo do empregador sobre o salário-maternidade. Para Receita e PGFN, a contribuição do segurado sobre essa parcela continua devida.", b: "RE 576.967 STF", p: "A decisão afastou só a cota patronal, não a do segurado." },
  { id: "est-contribuicao-previdencia-04", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "O terço de férias integra a base da contribuição?", v: "Sobre o terço das férias gozadas incide (tese do STF, Tema 985). Férias indenizadas e seu terço, inclusive a dobra, ficam fora por previsão expressa da Lei 8.212/91.", b: "art. 28, § 9º, 'd', Lei 8.212/91" },
  { id: "est-contribuicao-previdencia-05", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Incide contribuição sobre o aviso prévio indenizado e os 15 primeiros dias de afastamento por doença?", v: "Não. O STJ afastou a incidência sobre ambos, e a PGFN dispensa contestar e recorrer no caso do aviso prévio indenizado. O aviso prévio trabalhado, porém, integra a base.", b: "REsp 1.230.957/RS STJ" },
  { id: "est-contribuicao-previdencia-06", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "Quando a ajuda de custo por mudança de local de trabalho fica fora do salário de contribuição?", v: "Só quando paga em parcela única e exclusivamente pela mudança de local de trabalho. Paga em duas ou mais parcelas, todas sofrem incidência.", b: null, p: "Parcelamento da ajuda de custo faz incidir contribuição sobre todas as parcelas." },
  { id: "est-contribuicao-previdencia-07", d: "Direito Previdenciário", r: "E", t: "Contribuição previdenciária dos segurados", f: "O 13º salário sofre contribuição previdenciária?", v: "Sim, integra o salário de contribuição. Porém não entra no cálculo do salário de benefício.", b: "Súmula 688 STF" },
  { id: "est-responsabilidade-ambient-01", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Qual a natureza da responsabilidade civil por dano ambiental?", v: "Objetiva, independente de culpa, fundada na teoria do risco integral: basta o nexo causal e não se admitem excludentes como caso fortuito ou força maior.", b: null },
  { id: "est-responsabilidade-ambient-02", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "O comprador de imóvel degradado responde pelo dano causado pelo dono anterior?", v: "Sim. A obrigação ambiental é propter rem e pode ser cobrada do proprietário ou possuidor atual e/ou dos anteriores, à escolha do credor.", b: "Súmula 623 STJ" },
  { id: "est-responsabilidade-ambient-03", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Como responde o Poder Público que se omite na fiscalização ambiental?", v: "De forma solidária, mas com execução subsidiária: cobra-se primeiro o degradador direto.", b: "Súmula 652 STJ" },
  { id: "est-responsabilidade-ambient-04", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "A pretensão de reparar dano ambiental prescreve? E a punição administrativa?", v: "A reparação do dano ambiental difuso é imprescritível (STF e STJ). Já a apuração administrativa prescreve em 5 anos da prática ou da cessação da infração permanente, com prescrição intercorrente se o processo ficar parado mais de 3 anos.", b: null, p: "Se a infração também for crime, a prescrição administrativa segue o prazo da lei penal; e a prescrição da multa não afasta o dever de reparar." },
  { id: "est-responsabilidade-ambient-05", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Quais os requisitos para responsabilizar penalmente a pessoa jurídica por crime ambiental?", v: "A infração deve decorrer de decisão do representante legal ou contratual ou do órgão colegiado, no interesse ou benefício da entidade. Não se exige mais a dupla imputação com a pessoa física.", b: "art. 3º, Lei 9.605/1998" },
  { id: "est-responsabilidade-ambient-06", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Quais os limites da prestação pecuniária na Lei de Crimes Ambientais?", v: "Entre 1 e 360 salários-mínimos, paga à vítima ou a entidade com fim social; o valor é abatido de eventual reparação civil.", b: "art. 12, Lei 9.605/1998" },
  { id: "est-responsabilidade-ambient-07", d: "Direito Ambiental", r: "E", t: "Responsabilidade ambiental", f: "Como a reincidência agrava a multa administrativa ambiental?", v: "Nova infração em até 5 anos da decisão administrativa definitiva anterior: multa em triplo se for a mesma infração, em dobro se for infração diferente.", b: "art. 11, Decreto 6.514/2008" },
  { id: "est-conflito-de-leis-no-espa-01", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Que lei rege personalidade, nome, capacidade e direitos de família?", v: "A lei do país de domicílio da pessoa. Se o casamento for celebrado no Brasil, impedimentos dirimentes e formalidades seguem a lei brasileira.", b: "art. 7º LINDB" },
  { id: "est-conflito-de-leis-no-espa-02", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Que lei rege o regime de bens se os nubentes têm domicílios diferentes?", v: "A do primeiro domicílio conjugal, que também rege a invalidade do casamento. O local da celebração não decide.", b: "art. 7º, §§ 3º e 4º, LINDB" },
  { id: "est-conflito-de-leis-no-espa-03", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Qual a lei aplicável aos bens?", v: "A do país onde estão situados (lex rei sitae). Para móveis que o proprietário traz consigo ou destinados a transporte, aplica-se a lei do domicílio do proprietário.", b: "art. 8º LINDB" },
  { id: "est-conflito-de-leis-no-espa-04", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Que lei rege as obrigações contratuais com elemento estrangeiro?", v: "A do país onde se constituíram; o contrato considera-se constituído no lugar em que reside o proponente.", b: "art. 9º LINDB" },
  { id: "est-conflito-de-leis-no-espa-05", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Qual a lei da sucessão e qual a regra de proteção aos brasileiros?", v: "Vale a lei do último domicílio do falecido ou desaparecido, qualquer que seja o bem. Bens de estrangeiro no Brasil seguem a lei brasileira em favor do cônjuge ou filhos brasileiros se ela lhes for mais favorável; a capacidade para suceder segue o domicílio do herdeiro.", b: "art. 10 LINDB" },
  { id: "est-conflito-de-leis-no-espa-06", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Quando a competência da Justiça brasileira é concorrente e quando é exclusiva?", v: "Concorrente quando o réu tem domicílio no Brasil ou a obrigação deve ser cumprida aqui. Exclusiva nas ações sobre imóveis situados no Brasil e no inventário e partilha de bens aqui situados.", b: "art. 12 LINDB; arts. 21 e 23 CPC", p: "Ação proposta no exterior não gera litispendência; e cláusula de foro exclusivo estrangeiro só afasta a jurisdição brasileira se o réu a alegar na contestação (art. 25 CPC)." },
  { id: "est-conflito-de-leis-no-espa-07", d: "Direito Internacional", r: "E", t: "Conflito de leis no espaço", f: "Quem homologa sentença estrangeira no Brasil?", v: "O STJ, desde 2004. Também é preciso juiz competente, citação ou revelia regular, trânsito em julgado e tradução por intérprete autorizado.", b: "art. 15 LINDB", p: "O texto da LINDB ainda diz STF, mas a competência é do STJ." },
  { id: "est-dependentes-do-rgps-01", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Quais são as três classes de dependentes do RGPS?", v: "Classe I: cônjuge, companheiro(a) e filho não emancipado menor de 21 anos, inválido ou com deficiência intelectual, mental ou grave. Classe II: pais. Classe III: irmão nas mesmas condições do filho. Têm direito só à pensão por morte e ao auxílio-reclusão.", b: "art. 16, Lei 8.213/91" },
  { id: "est-dependentes-do-rgps-02", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Como concorrem os dependentes entre classes e dentro da mesma classe?", v: "Existindo dependente de uma classe, os das classes seguintes ficam excluídos. Dentro da mesma classe, o benefício é dividido em cotas iguais.", b: null },
  { id: "est-dependentes-do-rgps-03", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Quem precisa comprovar dependência econômica?", v: "Pais e irmãos. Na classe I a dependência é presumida, salvo para os equiparados a filho (enteado e menor tutelado), que dependem de declaração do segurado e de prova da dependência.", b: null },
  { id: "est-dependentes-do-rgps-04", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Filho de 22 anos universitário é dependente previdenciário?", v: "Não. Depois dos 21 o filho só segue dependente se inválido ou com deficiência intelectual, mental ou grave; a maioridade civil aos 18 também não altera o limite de 21.", b: null, p: "Não confundir com a dependência para Imposto de Renda, que alcança universitário até 24 anos." },
  { id: "est-dependentes-do-rgps-05", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "A ex-esposa que renunciou aos alimentos pode receber pensão por morte?", v: "Sim, se comprovar necessidade econômica superveniente. Quem recebia alimentos concorre em igualdade com a classe I; se os alimentos eram temporários, a pensão dura o prazo restante.", b: "Súmula 336 STJ" },
  { id: "est-dependentes-do-rgps-06", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Como se prova união estável ou dependência econômica perante o INSS?", v: "Com início de prova material contemporânea, produzida até 24 meses antes do óbito ou da prisão do segurado. Prova só testemunhal não basta, salvo força maior ou caso fortuito.", b: null },
  { id: "est-dependentes-do-rgps-07", d: "Direito Previdenciário", r: "E", t: "Dependentes do RGPS", f: "Quem perde definitivamente a condição de dependente?", v: "O condenado com trânsito em julgado como autor, coautor ou partícipe de homicídio doloso, consumado ou tentado, contra o segurado. Ficam ressalvados os absolutamente incapazes e os inimputáveis.", b: null },
  { id: "est-despesa-publica-precator-01", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Quais as fases da despesa pública e qual é obrigatória antes de qualquer gasto?", v: "Empenho, liquidação e pagamento. Nenhuma despesa pode ser feita sem prévio empenho, que reserva a dotação; a nota de empenho, porém, pode ser dispensada em casos especiais.", b: "art. 60, Lei 4.320/64" },
  { id: "est-despesa-publica-precator-02", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Diferencie restos a pagar processados e não processados.", v: "São despesas empenhadas e não pagas até 31/12. Processados já foram liquidados (credor tem direito líquido e certo); não processados ainda não foram liquidados.", b: "art. 36, Lei 4.320/64" },
  { id: "est-despesa-publica-precator-03", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "No regime geral, quando deve ser pago o precatório e há juros de mora nesse prazo?", v: "Apresentado até 1º de fevereiro, entra no orçamento do ano seguinte e deve ser pago até o fim desse exercício, com atualização monetária. Dentro desse prazo não correm juros de mora.", b: "art. 100, § 5º, CF" },
  { id: "est-despesa-publica-precator-04", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Quais os tetos de RPV quando o ente não edita lei própria?", v: "60 salários-mínimos na União (Lei 10.259/01), 40 para Estados e DF e 30 para Municípios. A lei local não pode fixar valor abaixo do maior benefício do RGPS.", b: "art. 87 ADCT" },
  { id: "est-despesa-publica-precator-05", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "O credor pode fracionar a execução para receber parte por RPV?", v: "Não; é vedado repartir o crédito para receber parte por RPV e o resto por precatório. Mas ele pode renunciar ao excedente e receber tudo por RPV.", b: "art. 100, § 8º, CF; art. 87, parágrafo único, ADCT" },
  { id: "est-despesa-publica-precator-06", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Como funciona a superpreferência dos precatórios alimentares?", v: "Titulares com 60 anos ou mais, doença grave ou deficiência recebem antes até o triplo do valor de RPV (no regime geral); o saldo segue na fila dos alimentares, que passam à frente dos comuns.", b: "art. 100, § 2º, CF", p: "A superpreferência não passa à frente das RPVs nem garante o pagamento integral de uma vez." },
  { id: "est-despesa-publica-precator-07", d: "Direito Financeiro", r: "E", t: "Despesa pública: precatórios e RPV", f: "Quais as regras da cessão de precatório?", v: "Pode ser total ou parcial e não depende de concordância do devedor, mas só produz efeitos após comunicação ao tribunal de origem e ao ente devedor. A cessão não muda a natureza do crédito: cessionário idoso não torna preferencial um precatório comum.", b: "art. 100, § 13, CF" },
  { id: "est-lei-das-eleicoes-e-acoes-01", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Qual o prazo e quem pode propor a AIRC?", v: "5 dias contados da publicação do edital de registro (prazo decadencial). Legitimados: candidato, partido, coligação e Ministério Público Eleitoral.", b: "Súmula 49 TSE" },
  { id: "est-lei-das-eleicoes-e-acoes-02", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Para que serve a AIJE, até quando cabe e quais as sanções?", v: "Apura abuso de poder econômico ou político e pode ser proposta até a diplomação. Gera inelegibilidade, cassação do registro ou do diploma e multa.", b: "art. 22, LC 64/90" },
  { id: "est-lei-das-eleicoes-e-acoes-03", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Qual o prazo e os fundamentos da AIME?", v: "15 dias contados da diplomação, por abuso de poder econômico, corrupção ou fraude. Tramita em segredo de justiça e pode levar à perda do mandato.", b: "art. 14, §§ 10 e 11, CF", p: "Não serve para conduta vedada isolada; abuso político só se entrelaçado com abuso econômico." },
  { id: "est-lei-das-eleicoes-e-acoes-04", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Candidato que dá bem ao eleitor em troca do voto: qual a ação e até quando?", v: "Representação por captação ilícita de sufrágio, cabível do registro até a diplomação. Gera multa e cassação do registro ou diploma; um único voto comprado basta e não se exige pedido explícito de voto.", b: "art. 41-A, Lei 9.504/97", p: "Segundo o TSE, só o candidato figura no polo passivo." },
  { id: "est-lei-das-eleicoes-e-acoes-05", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Qual o prazo e quem pode propor a representação por arrecadação e gastos ilícitos de campanha?", v: "15 dias contados da diplomação, por partido, coligação ou Ministério Público. Leva à negação ou cassação do diploma.", b: "art. 30-A, Lei 9.504/97", p: "O candidato não tem legitimidade ativa para essa representação." },
  { id: "est-lei-das-eleicoes-e-acoes-06", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Em que hipóteses e em que prazo cabe o RCED?", v: "Apenas por inelegibilidade superveniente, inelegibilidade constitucional ou falta de condição de elegibilidade, em 3 dias após a diplomação, com prova pré-constituída.", b: "art. 262, Código Eleitoral" },
  { id: "est-lei-das-eleicoes-e-acoes-07", d: "Direito Eleitoral", r: "E", t: "Lei das Eleições e ações eleitorais", f: "Como funciona a representação genérica por descumprimento da Lei das Eleições?", v: "Rito célere: defesa em 48 horas e decisão em 24 horas. Sanção ao candidato não atinge o partido beneficiado, salvo se provada a participação dele.", b: "art. 96, Lei 9.504/97" },
]);
